/// <summary>
/// MPJ_31513 Invoicing Design DCP 07/09/2022
/// Code clean up of classes KMPGPrintMgmtDocTypeEventHandler and KPMGPrintMgmtReportFormat
/// </summary>
Public class KPMGPrintMgtDocTypeHandler
{
}

Method.Source:
    /// <summary>
    /// MPJ_15231_Customer Statement DCP 14/02/2022
    /// Adds report to the print mgmt new node
    /// </summary>
    /// <param name = "_docType">doctype</param>
    /// <param name = "_result">result</param>
    [SubscribesTo(classStr(PrintMgmtDocType), delegateStr(PrintMgmtDocType, getDefaultReportFormatDelegate))]
    public static void getDefaultReportFormatDelegate(PrintMgmtDocumentType _docType, EventHandlerResult _result)
    {
        switch(_docType)
        {
            case PrintMgmtDocumentType::KPMGMultiCustAccountStatement:
                _result.result(ssrsReportStr(KPMGCustAccountStatementExt, ReportMultiCust));
                break;

            case PrintMgmtDocumentType::SalesOrderConfirmation:
                if (_result.result() == null || strStartsWith(_result.result(), 'SalesConfirm'))
                {
                    _result.result(ssrsReportStr(KPMGSalesConfirm, Report));
                }
                break;

            /* USE ssrsReportStr(METSalesInvoice, MFG) from class METPrintMgtDocTypeHandler
            case PrintMgmtDocumentType::SalesOrderInvoice:

                if (_result.result() == null || strStartsWith(_result.result(), 'SalesInvoice'))
                {
                    _result.result(ssrsReportStr(KPMGSalesInvoice, Report));
                }
                break;
            */
            case PrintMgmtDocumentType::PurchaseOrderRequisition:
            case PrintMgmtDocumentType::PurchaseOrderConfirmationRequest:
                
                if (curExt() == METConstants::Food)
                {
                    _result.result(ssrsReportStr(KPMGPurchPurchaseOrder, Food));
                }
                else if (curExt() == METConstants::Liquor)
                {
                    _result.result(ssrsReportStr(KPMGPurchPurchaseOrder, Liquor));
                }
                else if (curExt() == METConstants::Hardware)
                {
                    _result.result(ssrsReportStr(KPMGPurchPurchaseOrder, Hardware));
                }
                break;

            case PrintMgmtDocumentType::SalesOrderPackingSlip:
                if (_result.result() == null || strStartsWith(_result.result(), 'SalesPackingSlip'))
                {
                    _result.result(ssrsReportStr(KPMGSalesPackingSlip, Report));
                }
                break;

            case PrintMgmtDocumentType::SIManagedProjInvoice:
                if (_result.result() == null || strStartsWith(_result.result(), 'PSAManageInvoice'))
                {
                    _result.result(ssrsReportStr(KPMGPSAManageInvoice, Report));
                }
                break;

            case PrintMgmtDocumentType::SIProjInvoice:
                if (_result.result() == null || strStartsWith(_result.result(), 'PSAProjInvoice'))
                {
                    _result.result(ssrsReportStr(KPMGPSAProjInvoice, Report));
                }
                break;

            case PrintMgmtDocumentType::CustAccountStatement:

                if (_result.result() == null || strStartsWith(_result.result(), 'CustAccountStatement'))
                {
                    if (curExt() == '2002')
                    {
                        _result.result(ssrsReportStr(KPMGCustAccountStatementExt, ReportTasLiq));
                    }
                    else
                    {
                        _result.result(ssrsReportStr(KPMGCustAccountStatementExt, Report));
                    }
                }
                break;

            case PrintMgmtDocumentType::Quotation :
                if (_result.result() == null || strStartsWith(_result.result(), 'SalesQuotation'))
                {
                    _result.result(ssrsReportStr(KPMGSalesQuotation, Report));
                }
                break;

            case PrintMgmtDocumentType::SalesFreeTextInvoice :
                if (_result.result() == null || strStartsWith(_result.result(), 'FreeTextInvoice'))
                {
                    _result.result(ssrsReportStr(KPMGFreeTextInvoice, Report));
                }
                break;
            
            case PrintMgmtDocumentType::PurchRFQ :
                if (_result.result() == null || strStartsWith(_result.result(), 'RFQSend'))
                {
                    _result.result(ssrsReportStr(KPMGRFQSend, Report));
                }
                break;

            default:
                break;
        }
    }
